if ($event eq 'PreToolUse' || $event eq 'PostToolUse' || $event eq 'PostToolUseFailure') {
    $out{tool_name}   = $payload->{tool_name}   if defined $payload->{tool_name};
    $out{tool_use_id} = $payload->{tool_use_id} if defined $payload->{tool_use_id};
}
