(() => {
  const tile = document.querySelector('.filmstrip-tile');
  if (!tile) return {err:'no tile'};
  const walk = [];
  const rec = (el, d) => {
    const cs = getComputedStyle(el);
    walk.push({
      d, tag: el.tagName, cls: el.className,
      txt: (el.childElementCount===0 ? (el.textContent||'').trim().slice(0,20) : ''),
      bg: cs.backgroundColor, w: el.offsetWidth, h: el.offsetHeight,
      radius: cs.borderRadius
    });
    [...el.children].forEach(c => rec(c, d+1));
  };
  rec(tile, 0);
  return walk;
})()

