(() => {
  const rows = [...document.querySelectorAll('button.picker-recent')];
  return {onPicker: !!document.querySelector('[class*="picker"]'), rows: rows.map(r=>(r.textContent||'').slice(0,22)), tiles: document.querySelectorAll('[class*="filmstrip-tile"]').length};
